sqlEquivalent:
CREATE TABLE lab_bloggers (id SERIAL PRIMARY KEY, handle VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE lab_posts (
  id SERIAL PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  blogger_id INTEGER NOT NULL REFERENCES lab_bloggers(id)
);
CREATE TABLE lab_tags (id SERIAL PRIMARY KEY, label VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE lab_post_tags (
  post_id INTEGER NOT NULL REFERENCES lab_posts(id) ON DELETE CASCADE,
  tag_id INTEGER NOT NULL REFERENCES lab_tags(id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, tag_id)
);

starterCode:
// JavaScript track — same Prisma DSL
model LabBlogger {
  id Int @id @default(autoincrement())
  handle String @unique
  posts LabPost[]
  @@map("lab_bloggers")
}
model LabPost {
  id Int @id @default(autoincrement())
  title String
  bloggerId Int @map("blogger_id")
  blogger LabBlogger @relation(fields: [bloggerId], references: [id])
  tags LabPostTag[]
  @@map("lab_posts")
}
model LabTag {
  id Int @id @default(autoincrement())
  label String @unique
  posts LabPostTag[]
  @@map("lab_tags")
}
model LabPostTag {
  postId Int @map("post_id")
  tagId Int @map("tag_id")
  post LabPost @relation(fields: [postId], references: [id], onDelete: Cascade)
  tag LabTag @relation(fields: [tagId], references: [id], onDelete: Cascade)
  @@id([postId, tagId])
  @@map("lab_post_tags")
}
